<?php require_once __DIR__.'/includes/functions.php'; if(current_user()) { if(current_user()['role']==='admin') redirect('/admin/index.php'); if(current_user()['role']==='parent') redirect('/parent/index.php'); redirect('/hospital/index.php'); } $error=''; if($_SERVER['REQUEST_METHOD']==='POST'){ verify_csrf(); $email=filter_var(trim($_POST['email']??''),FILTER_VALIDATE_EMAIL); $stmt=db()->prepare("SELECT id,name,email,password_hash,role,status FROM users WHERE email=? AND role='admin' LIMIT 1"); $stmt->execute([$email ?: '']); $user=$stmt->fetch(); if($user && password_verify($_POST['password']??'', $user['password_hash']) && $user['status']==='active'){ session_regenerate_id(true); $_SESSION['user']=['id'=>$user['id'],'name'=>$user['name'],'email'=>$user['email'],'role'=>'admin']; redirect('/admin/index.php'); } $error='Administrator credentials are incorrect.'; } $pageTitle='Administrator access'; require __DIR__.'/includes/header.php'; ?>
